+	rp->state = RW_READER;
+	r->nreaders++;
+	return true;
+}
+
+/// Parte C++ della primitiva rw_upgrade()
+extern "C" void c_rw_upgrade(natl rw)
+{
+	if (!rw_valido(rw)) {
+		flog(LOG_WARN, "rw_upgrade(%d): rwlock non valido", rw);
+		c_abort_p();
+		return;
+	}
+
+	des_rw *r = &array_desrw[rw];
+	des_proc_rw *rp = rw_proc_find(r, esecuzione);
+	if (!rp) {
+		flog(LOG_WARN, "rw_upgrade(%d): processo non ha lock su rwlock", rw);
+		c_abort_p();
+		return;
+	}
+
+	if (rp->state != RW_READER && rp->state != RW_UPGRADED) {
+		flog(LOG_WARN, "rw_upgrade(%d): processo non ha lock di lettura su rwlock", rw);
+		c_abort_p();
+		return;
+	}
+
+	// Se siamo l'unico lettore, possiamo fare l'upgrade immediatamente
+	if (r->nreaders == 1 && r->w_writers == nullptr) {
+		rp->state = RW_UPGRADED;
+		r->writer = esecuzione->id;
+		return;
+	}
+
+// Altrimenti dobbiamo rilasciare il read lock e mettere il processo in attesa
+// dei writers in coda
+rp->state = RW_NONE;
+r->nreaders--;
+
+// Se era l'ultimo lettore, rimuoviamo dal writer pool
+des_proc* w = r->w_writers;
+if (w && w == esecuzione) {
+    r->w_writers = w->puntatore;
+}
+inserimento_lista(r->w_writers, esecuzione);
+schedulatore();
+}
+
+/// Parte C++ della primitiva rw_downgrade()
+extern "C" void c_rw_downgrade(natl rw)
+{
+	if (!rw_valido(rw)) {
+		flog(LOG_WARN, "rw_downgrade(%d): rwlock non valido", rw);
+		c_abort_p();
+		return;
+	}
+
+	des_rw *r = &array_desrw[rw];
+	des_proc_rw *rp = rw_proc_find(r, esecuzione);
+	if (!rp) {
+		flog(LOG_WARN, "rw_downgrade(%d): processo non ha lock su rwlock", rw);
+		c_abort_p();
+		return;
+	}
+
+	if (rp->state == RW_NONE) {
+		flog(LOG_WARN, "rw_downgrade(%d): processo non ha lock su rwlock", rw);
+		c_abort_p();
+		return;
+	}
+
+	// Se abbiamo un upgrade, lo trasformiamo in read lock
+	if (rp->state == RW_UPGRADED) {
 		rp->state = RW_READER;
+		r->writer = 0;
 		r->nreaders++;
+		return;
+	}
+
+	// Rilascio del lock
+	if (rp->state == RW_WRITER) {
+		r->writer = 0;
+		r->nreaders = 0;
+		schedulatore();
+	} else if (rp->state == RW_UPGRADED) {
+		r->writer = 0;
+		r->nreaders++;
+		schedulatore();
+	} else {
+		r->nreaders--;
+		schedulatore();
 	}
+	rp->state = RW_NONE;
 }
